//! JSON Schema validation for the config and manifest documents.
//!
//! The schemas are generated by [`crate::model::schema`] with `schemars` (Draft
//! 2020-12) and validated here with the [`jsonschema`] crate, which replaces
//! the previous hand-rolled subset validator.

use jsonschema::error::ValidationErrorKind;
use serde_json::Value;

use crate::error::{Error, Result};

/// Validate `instance` against `schema` (a root schema, typically produced by
/// [`crate::model::schema`]).
///
/// The schema's draft is auto-detected from its `$schema` keyword (schemars
/// emits Draft 2020-12). On failure the first validation error is reported with
/// a JSON-pointer instance path, followed by a count of any further errors.
pub fn validate(instance: &Value, schema: &Value) -> Result<()> {
    let validator = jsonschema::validator_for(schema)
        .map_err(|e| Error::msg(format!("invalid JSON schema: {e}")))?;

    let errors: Vec<_> = validator.iter_errors(instance).collect();
    if errors.is_empty() {
        return Ok(());
    }

    // The first error is the one reported. For a discriminated `oneOf`
    // (schemars tagged-union), the library only reports that no subschema
    // matched; surface the nested error from the variant whose `type`
    // discriminator matches the instance, which is far more actionable.
    let first = &errors[0];
    let (path, msg) = match refine_oneof(schema, instance, first) {
        Some(refined) => refined,
        None => match refine_anyof(first) {
            Some(refined) => refined,
            None => (
                first.instance_path().as_str().to_string(),
                first.to_string(),
            ),
        },
    };

    let suffix = if errors.len() > 1 {
        format!(" (and {} more validation error(s))", errors.len() - 1)
    } else {
        String::new()
    };
    let msg = if path.is_empty() {
        format!("Schema validation failed: {msg}{suffix}")
    } else {
        format!("Schema validation failed at {path}: {msg}{suffix}")
    };
    Err(Error::msg(msg))
}

/// For a `oneOf` failure on an object carrying a `type` discriminator, drill
/// into the subschema whose `type` const matches and return its first nested
/// error (with an instance path made absolute against the root instance).
///
/// Returns `None` when the error is not a `oneOf` failure, the instance has no
/// `type` field, or no variant matches (e.g. an unknown tag value) — in those
/// cases the original library error is reported as-is.
fn refine_oneof(
    root: &Value,
    root_instance: &Value,
    err: &jsonschema::ValidationError,
) -> Option<(String, String)> {
    let context = match err.kind() {
        ValidationErrorKind::OneOfNotValid { context } => context,
        _ => return None,
    };

    let instance = root_instance
        .pointer(err.instance_path().as_str())
        .unwrap_or(root_instance);
    let disc = instance
        .as_object()
        .and_then(|m| m.get("type"))
        .and_then(|v| v.as_str())?
        .to_string();

    let one_of = root.pointer(err.schema_path().as_str())?.as_array()?;

    for (i, entry) in one_of.iter().enumerate() {
        let entry_const = entry
            .get("properties")
            .and_then(|p| p.get("type"))
            .and_then(|t| t.get("const"))
            .and_then(|c| c.as_str());
        if entry_const == Some(disc.as_str())
            && let Some(nested) = context.get(i).and_then(|v| v.first())
        {
            let full_path = join_paths(
                err.instance_path().as_str(),
                nested.instance_path().as_str(),
            );
            return Some((full_path, nested.to_string()));
        }
    }

    None
}

/// For an `anyOf` failure (schemars emits `anyOf: [{$ref: T}, {type: null}]`
/// for `Option<T>`), surface the nested error from the non-null branch — the
/// null branch only produces a `Type` mismatch which is not actionable.
///
/// Recurses through nested `anyOf`/`oneOf` failures (e.g. `Option<struct>`
/// whose field is itself `Option<struct>`) so the leaf cause — typically an
/// `AdditionalProperties` or `Type` error — is reported instead of a generic
/// "not valid under anyOf" message.
///
/// Returns `None` when the error is not an `anyOf` failure or no non-null
/// branch error is found.
fn refine_anyof(err: &jsonschema::ValidationError) -> Option<(String, String)> {
    let context = match err.kind() {
        ValidationErrorKind::AnyOf { context } => context,
        _ => return None,
    };
    for branch_errors in context {
        if let Some(nested) = branch_errors.first()
            && !matches!(nested.kind(), ValidationErrorKind::Type { .. })
        {
            // Recurse into nested anyOf/oneOf so deeply-nested Option<struct>
            // errors surface their leaf cause.
            if let Some(inner) = refine_anyof(nested).or_else(|| refine_oneof_err(nested)) {
                let full_path = join_paths(err.instance_path().as_str(), &inner.0);
                return Some((full_path, inner.1));
            }
            let full_path = join_paths(
                err.instance_path().as_str(),
                nested.instance_path().as_str(),
            );
            return Some((full_path, nested.to_string()));
        }
    }
    None
}

/// Like [`refine_oneof`] but operates on a single nested error rather than the
/// root schema/instance (best-effort, used only to recurse from [`refine_anyof`]).
fn refine_oneof_err(err: &jsonschema::ValidationError) -> Option<(String, String)> {
    let context = match err.kind() {
        ValidationErrorKind::OneOfNotValid { context } => context,
        _ => return None,
    };
    for branch_errors in context {
        if let Some(nested) = branch_errors.first() {
            if let Some(inner) = refine_anyof(nested).or_else(|| refine_oneof_err(nested)) {
                let full_path = join_paths(err.instance_path().as_str(), &inner.0);
                return Some((full_path, inner.1));
            }
            let full_path = join_paths(
                err.instance_path().as_str(),
                nested.instance_path().as_str(),
            );
            return Some((full_path, nested.to_string()));
        }
    }
    None
}

/// Concatenate two JSON-pointer instance paths (each `""` or `/...`).
fn join_paths(prefix: &str, suffix: &str) -> String {
    match (prefix.is_empty(), suffix.is_empty()) {
        (true, _) => suffix.to_string(),
        (_, true) => prefix.to_string(),
        _ => format!("{prefix}{suffix}"),
    }
}
